import sys

MOD = 1_000_000_007


def fib_mod(n):
    # fast doubling: returns F(n) mod MOD
    a, b = 0, 1  # F(0), F(1)
    for bit in bin(n)[2:]:
        # doubling step
        c = a * ((2 * b - a) % MOD) % MOD          # F(2k)
        d = (a * a + b * b) % MOD                  # F(2k+1)
        if bit == '1':
            a, b = d, (c + d) % MOD
        else:
            a, b = c, d
    return a


def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        out.append(str(fib_mod(int(s))))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
